import {CITY_INCOME,INCOME_BINS,SHORTLIST,isNumber,colorFor,money,number,percent,bubbleRadius,searchFeatures,escapeHtml as esc} from './map-utils.mjs';
const $=id=>document.getElementById(id);
const mobile=()=>window.matchMedia('(max-width:760px)').matches;
const reduced=()=>window.matchMedia('(prefers-reduced-motion:reduce)').matches;
let features=[],featureByCode=new Map(),layers=new Map(),bubbles=new Map(),selected='ASP',hovered=null,mode='count',showBubbles=true,showLabels=true,map,geo,bubbleGroup,labelGroup,tiles,tileErrors=0,tileSuccess=0,searchMatches=[],activeSearch=-1;
const sidebar=document.querySelector('.sidebar'),layerPanel=document.querySelector('.layer-panel');
function syncLayerPanel(){const parent=mobile()?$('mobile-layers'):sidebar;if(layerPanel.parentElement!==parent){if(mobile())parent.append(layerPanel);else sidebar.insertBefore(layerPanel,$('detail-panel'));}if(!mobile()){$('mobile-layers').hidden=true;$('mobile-layers-button').setAttribute('aria-expanded','false');}}
syncLayerPanel();
if(mobile()){sidebar.classList.add('collapsed');$('mobile-detail-handle').setAttribute('aria-expanded','false');$('mobile-chevron').textContent='⌃';}
for(const bin of INCOME_BINS){const s=document.createElement('span');s.style.background=bin.color;s.title=bin.label;$('income-ramp').append(s);}
function updateBubbleLegend(){const vals=mode==='count'?[500,2000,6000]:[.05,.2,.4];$('bubble-legend').innerHTML=vals.map(v=>`<div class="bubble-example"><span class="bubble-symbol" style="width:${bubbleRadius(v,mode)*2*(mobile()?.7:1)}px;height:${bubbleRadius(v,mode)*2*(mobile()?.7:1)}px"></span><span>${mode==='count'?number(v):percent(v)}</span></div>`).join('');$('bubble-description').textContent=mode==='count'?'圆面积代表人数；无圆点可能为0或缺数据。':'圆面积代表占比；无圆点可能为0或缺数据。';}
updateBubbleLegend();
function baseStyle(f){const p=f.properties;return{color:p.income===null?'#aebbb4':'#f5f6e8',weight:.8,opacity:.85,fillColor:colorFor(p.income),fillOpacity:p.income===null?.35:.73,dashArray:p.income===null?'3 3':null};}
function selectedStyle(f){return{...baseStyle(f),color:'#234d47',weight:2.6,opacity:1,fillOpacity:.8};}
function refreshOutlines(){for(const [code,layer]of layers){layer.setStyle(code===selected?selectedStyle(layer.feature):baseStyle(layer.feature));}if(layers.get(selected))layers.get(selected).bringToFront();}
function renderDetail(f,preview=false){if(!f)return;const p=f.properties;$('community-name').textContent=p.name;$('mobile-selection-label').textContent=preview?'悬停预览':'社区详情';$('community-meta').innerHTML=`<span>${esc(p.sectorLabel||'片区未注明')}</span><span>${esc(p.typeLabel||p.type)}</span>`;$('selection-status').textContent=preview?'悬停预览 · 点击固定':SHORTLIST.includes(p.code)?'关注社区':'已选社区';$('income-value').textContent=money(p.income);$('collapsed-summary').textContent='2020 收入 '+money(p.income)+' · 华人 '+number(p.chineseCount)+'（'+percent(p.chinesePct)+'）';$('income-value').style.color=isNumber(p.income)?'#294d4b':'#83918b';$('income-context').textContent=isNumber(p.income)?`全市的 ${(p.income/CITY_INCOME).toFixed(2)} 倍 · 收入第 ${p.incomeRank} / 205 名`:'官方档案没有同口径收入数值';$('chinese-count').textContent=number(p.chineseCount);$('chinese-percent').textContent=percent(p.chinesePct);$('children').textContent=percent(p.children);$('household').textContent=isNumber(p.householdSize)?p.householdSize.toFixed(1)+' 人':'—';$('population').textContent=number(p.population);$('community-note').textContent=p.note||'暂无社区参考说明。';$('data-caveat').textContent=p.caveat||'';$('data-caveat').hidden=!p.caveat;const link=$('source-link');link.hidden=!p.sourceUrl;if(p.sourceUrl)link.href=p.sourceUrl;$('focus-community').dataset.code=p.code;}
function focusCode(code,zoom=true,expand=true){const f=featureByCode.get(code);if(!f)return;selected=code;hovered=null;if(mobile()&&expand){sidebar.classList.remove('collapsed');$('mobile-detail-handle').setAttribute('aria-expanded','true');$('mobile-chevron').textContent='⌄';}renderDetail(f);refreshOutlines();document.querySelectorAll('.shortcut').forEach(b=>b.classList.toggle('active',b.dataset.code===code));if(zoom)fitFeature(code);$('announcer').textContent=`已选择 ${f.properties.name}。家庭收入 ${money(f.properties.income)}，华人人数 ${number(f.properties.chineseCount)}。`;try{history.replaceState(null,'','#'+encodeURIComponent(code));}catch{}updateLabels();}
function padding(){return mobile()?{paddingTopLeft:[28,115],paddingBottomRight:[28,Math.min(310,document.querySelector('.map-section').clientHeight*.44)],maxZoom:13.2,animate:!reduced()}:{padding:[70,90],maxZoom:13.2,animate:!reduced()};}
function fitFeature(code){const l=layers.get(code);if(l){map.fitBounds(l.getBounds(),padding());}}
function fitCity(){if(!geo)return;const p=mobile()?{paddingTopLeft:[15,95],paddingBottomRight:[15,sidebar.classList.contains('collapsed')?165:Math.min(370,document.querySelector('.map-section').clientHeight*.5)]}:{paddingTopLeft:[25,65],paddingBottomRight:[25,115]};map.fitBounds(geo.getBounds(),{...p,animate:!reduced()});}
function tooltip(p){return`<strong>${esc(p.name)}</strong>收入 ${money(p.income)}<br>华人 ${number(p.chineseCount)} 人 · ${percent(p.chinesePct)}<span class="tip-note">${esc(p.note)}</span>`;}
function bindFeature(f,layer){const p=f.properties;layers.set(p.code,layer);layer.on('add',()=>{layer.getElement()?.setAttribute('data-community',p.code);});layer.on('click',()=>{focusCode(p.code,false);$('mobile-layers').hidden=true;$('mobile-layers-button').setAttribute('aria-expanded','false');});layer.on('mouseover',()=>{if(mobile())return;hovered=p.code;layer.setStyle({weight:2.3,color:'#486b60',fillOpacity:.88});layer.bringToFront();renderDetail(f,true);});layer.on('mouseout',()=>{if(mobile())return;hovered=null;layer.setStyle(p.code===selected?selectedStyle(f):baseStyle(f));renderDetail(featureByCode.get(selected));layers.get(selected)?.bringToFront();});if(!mobile())layer.bindTooltip(tooltip(p),{className:'community-tooltip',direction:'top',sticky:true,offset:[0,-10],opacity:.98});}
function updateBubbles(){if(!map)return;bubbleGroup.clearLayers();bubbles.clear();if(!showBubbles)return;const sorted=[...features].filter(f=>isNumber(mode==='count'?f.properties.chineseCount:f.properties.chinesePct)).sort((a,b)=>(mode==='count'?b.properties.chineseCount-a.properties.chineseCount:b.properties.chinesePct-a.properties.chinesePct));for(const f of sorted){const p=f.properties;const val=mode==='count'?p.chineseCount:p.chinesePct;const r=bubbleRadius(val,mode,map.getZoom())*(mobile()?.7:1);if(r===0)continue;const c=L.circleMarker([p.centroid[1],p.centroid[0]],{radius:r,color:'#284d59',weight:1.3,fillColor:'#2b5363',fillOpacity:.15,opacity:.8,pane:'bubbles',bubblingMouseEvents:false}).addTo(bubbleGroup);c.on('click',()=>focusCode(p.code,false));if(!mobile()){c.bindTooltip(tooltip(p),{className:'community-tooltip',direction:'top',offset:[0,-r-3]});c.on('mouseover',()=>{hovered=p.code;renderDetail(f,true);layers.get(p.code)?.setStyle({color:'#244f45',weight:2.3});});c.on('mouseout',()=>{hovered=null;renderDetail(featureByCode.get(selected));refreshOutlines();});}bubbles.set(p.code,c);}}
function updateLabels(){if(!map)return;labelGroup.clearLayers();if(!showLabels)return;const zoom=map.getZoom();const bounds=map.getBounds();let candidates=features.filter(f=>bounds.contains([f.properties.centroid[1],f.properties.centroid[0]])&&(f.properties.type==='Residential'||f.properties.code===selected));candidates.sort((a,b)=>{const priority=p=>p.code===selected?0:SHORTLIST.includes(p.code)?1:2;return priority(a.properties)-priority(b.properties)||(b.properties.population||0)-(a.properties.population||0);});const occupied=[];for(const f of candidates){const p=f.properties;const priority=p.code===selected||SHORTLIST.includes(p.code);if(zoom<11&&!priority&&!(p.chineseCount>=2500))continue;const ll=[p.centroid[1],p.centroid[0]],pt=map.latLngToContainerPoint(ll);const labelWidth=Math.min(160,p.name.length*(priority?6:4.9));const box={x:pt.x-labelWidth/2,y:pt.y+8,w:labelWidth,h:priority?19:15};if(occupied.some(b=>box.x<b.x+b.w+5&&box.x+box.w+5>b.x&&box.y<b.y+b.h+4&&box.y+box.h+4>b.y)&&p.code!==selected)continue;occupied.push(box);const icon=L.divIcon({className:'community-label'+(priority?' focus-label':''),html:esc(p.name),iconSize:[labelWidth,20],iconAnchor:[labelWidth/2,-8]});L.marker(ll,{icon,interactive:false,keyboard:false,pane:'labels'}).addTo(labelGroup);}}
function selectMode(newMode){mode=newMode;$('count-mode').classList.toggle('active',mode==='count');$('percent-mode').classList.toggle('active',mode==='percent');$('count-mode').setAttribute('aria-pressed',String(mode==='count'));$('percent-mode').setAttribute('aria-pressed',String(mode==='percent'));updateBubbleLegend();updateBubbles();}
$('count-mode').addEventListener('click',()=>selectMode('count'));$('percent-mode').addEventListener('click',()=>selectMode('percent'));
$('bubbles-toggle').addEventListener('change',e=>{showBubbles=e.target.checked;updateBubbles();});$('labels-toggle').addEventListener('change',e=>{showLabels=e.target.checked;updateLabels();});
$('roads-toggle').addEventListener('change',e=>{if(!map)return;if(e.target.checked)tiles.addTo(map);else tiles.remove();});
$('fit-city').addEventListener('click',fitCity);$('zoom-in').addEventListener('click',()=>map?.zoomIn(.5));$('zoom-out').addEventListener('click',()=>map?.zoomOut(.5));$('focus-community').addEventListener('click',e=>focusCode(e.currentTarget.dataset.code));
$('mobile-layers-button').addEventListener('click',()=>{const open=$('mobile-layers').hidden;$('mobile-layers').hidden=!open;$('mobile-layers-button').setAttribute('aria-expanded',String(open));});
$('mobile-detail-handle').addEventListener('click',()=>{const collapsed=sidebar.classList.toggle('collapsed');$('mobile-detail-handle').setAttribute('aria-expanded',String(!collapsed));$('mobile-chevron').textContent=collapsed?'⌃':'⌄';});
const dialog=$('method-dialog');$('method-button').addEventListener('click',()=>dialog.showModal());$('close-method').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
function closeSearch(){$('search-results').hidden=true;$('search').setAttribute('aria-expanded','false');$('search').removeAttribute('aria-activedescendant');activeSearch=-1;}
function renderSearch(){const q=$('search').value.trim();searchMatches=searchFeatures(features,q);activeSearch=-1;if(!q){closeSearch();return;}$('search-results').hidden=false;$('search').setAttribute('aria-expanded','true');$('search-results').innerHTML=searchMatches.length?searchMatches.map((f,i)=>{const p=f.properties;return`<button class="search-result" id="search-option-${i}" role="option" aria-selected="false" data-code="${esc(p.code)}"><span><strong>${esc(p.name)}</strong><small>${esc(p.sectorLabel)} · ${esc(p.typeLabel)}</small></span><span>${money(p.income)}</span></button>`;}).join(''):'<div class="no-results">没有找到这个社区。可输入英文名或社区代码。</div>';}
$('search').addEventListener('input',renderSearch);$('search').addEventListener('focus',()=>{if($('search').value)renderSearch();});$('search-results').addEventListener('click',e=>{const b=e.target.closest('[data-code]');if(b){focusCode(b.dataset.code);$('search').value='';closeSearch();$('search').blur();}});
$('search').addEventListener('keydown',e=>{if(e.key==='Escape'){closeSearch();$('search').blur();}if((e.key==='ArrowDown'||e.key==='ArrowUp')&&searchMatches.length){e.preventDefault();activeSearch=(activeSearch+(e.key==='ArrowDown'?1:-1)+searchMatches.length)%searchMatches.length;document.querySelectorAll('.search-result').forEach((b,i)=>{b.classList.toggle('active',i===activeSearch);b.setAttribute('aria-selected',String(i===activeSearch));});const el=$('search-option-'+activeSearch);$('search').setAttribute('aria-activedescendant',el.id);el.scrollIntoView({block:'nearest'});}if(e.key==='Enter'&&searchMatches.length){e.preventDefault();const f=searchMatches[Math.max(0,activeSearch)];focusCode(f.properties.code);$('search').value='';closeSearch();$('search').blur();}});
document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))closeSearch();});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!dialog.open){e.preventDefault();$('search').focus();}});
let resizeTimer;window.addEventListener('resize',()=>{syncLayerPanel();clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{map?.invalidateSize();updateLabels();updateBubbles();updateBubbleLegend();},150);});
async function loadBasemap(){
  try{
    const response=await fetch('./basemap.geojson');
    if(!response.ok)throw Error('主要道路数据尚未就绪');
    const data=await response.json();
    map.createPane('water');map.getPane('water').style.zIndex=410;map.getPane('water').style.pointerEvents='none';
    map.createPane('roads');map.getPane('roads').style.zIndex=420;map.getPane('roads').style.pointerEvents='none';
    L.geoJSON(data,{filter:f=>f.properties.kind==='water',pane:'water',interactive:false,style:{color:'#84b6c3',weight:.6,fillColor:'#a7ccd3',fillOpacity:.88}}).addTo(map);
    L.geoJSON(data,{filter:f=>f.properties.kind==='road',pane:'roads',interactive:false,style:{color:'#667f70',weight:2.3,opacity:.35}}).addTo(tiles);
    L.geoJSON(data,{filter:f=>f.properties.kind==='road',pane:'roads',interactive:false,style:{color:'#fffff4',weight:1.1,opacity:.85}}).addTo(tiles);
    $('map-warning').hidden=true;
  }catch(error){$('map-warning').textContent='道路参考图暂未载入，社区边界与统计数据仍可使用。';$('map-warning').hidden=false;}
}
async function init(){try{if(!window.L)throw new Error('地图组件未能载入');const response=await fetch('./communities.geojson');if(!response.ok)throw new Error('社区数据未能载入');const data=await response.json();features=data.features;featureByCode=new Map(features.map(f=>[f.properties.code,f]));map=L.map('map',{zoomControl:false,zoomSnap:.25,zoomDelta:.5,minZoom:8,maxZoom:17,preferCanvas:false,attributionControl:true});map.createPane('bubbles');map.getPane('bubbles').style.zIndex=450;map.createPane('labels');map.getPane('labels').style.zIndex=470;map.getPane('labels').style.pointerEvents='none';tiles=L.layerGroup().addTo(map);loadBasemap();map.attributionControl.setPrefix(false);map.attributionControl.addAttribution('边界与统计：<a href="https://www.calgary.ca/communities/profiles.html" target="_blank" rel="noopener">City of Calgary</a>');geo=L.geoJSON(data,{style:baseStyle,onEachFeature:bindFeature}).addTo(map);bubbleGroup=L.layerGroup().addTo(map);labelGroup=L.layerGroup().addTo(map);map.on('zoomend',()=>{updateBubbles();updateLabels();});map.on('moveend',updateLabels);for(const code of SHORTLIST){const f=featureByCode.get(code);if(!f)continue;const b=document.createElement('button');b.className='shortcut';b.dataset.code=code;b.textContent=f.properties.name;b.addEventListener('click',()=>focusCode(code));$('shortcuts').append(b);}const hash=decodeURIComponent(location.hash.slice(1));selected=featureByCode.has(hash)?hash:'ASP';$('coverage-text').textContent=`313 个区域 · 2021 普查`;$('loading-overlay').hidden=true;fitCity();focusCode(selected,false,false);updateBubbles();updateLabels();if(hash&&featureByCode.has(hash))fitFeature(hash);if(mobile())$('map-hint').textContent='点击社区查看详情';}catch(error){$('loading-overlay').innerHTML=`<strong>地图暂时无法载入</strong><span>${esc(error.message)}</span><button class="map-button" id="retry">重新载入</button>`;$('retry').addEventListener('click',()=>location.reload());$('coverage-text').textContent='数据载入失败';}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
